mapper.update:
update ai_chat_run
   set status = 'FINALIZING', heartbeat_time = #{now},
       update_time = #{now}
 where run_id = #{runId} and worker_id = #{workerId}
   and status = 'RUNNING' and cancel_requested = '0'

update ai_chat_run
   set heartbeat_time = #{now}, update_time = #{now}
 where run_id = #{runId} and worker_id = #{workerId}
   and status in ('QUEUED', 'RUNNING', 'FINALIZING')

update ai_chat_run
   set last_event_seq = greatest(last_event_seq, #{seq}), update_time = current_timestamp
 where run_id = #{runId}

update ai_chat_run
   set status = 'INTERRUPTED', active_key = null, error_code = 'WORKER_STALE',
       error_message = '执行节点心跳超时', finished_time = #{now}, update_time = #{now}
 where status in ('QUEUED', 'RUNNING', 'FINALIZING')
   and coalesce(heartbeat_time, create_time) < #{staleBefore}
